  ["Night"] = "나이트",
  ["Glass"] = "글래스",
  ["Graphite"] = "그래파이트",
  -- the search syntax (ADR 0045)
  ["Search syntax"] = "검색 문법",
  ["Fields: %s (field:word, level>30)"] = "필드: %s (필드:단어, level>30)",
  ["type (npc, item, quest, zone, ...)"] = "type (npc, item, quest, zone, ...)",
  ['wolf den: every word   "den mother": the phrase'] = 'wolf den: 모든 단어   "den mother": 구절',
  ["wolf OR boar: either   -rabid: not   ( ): groups"] = "wolf OR boar: 둘 중 하나   -rabid: 제외   ( ): 묶음",
  ["heal*: any letters   /^wt[bs]/: a Lua pattern"] = "heal*: 아무 글자   /^wt[bs]/: Lua 패턴",
  ["A quote is not closed."] = "따옴표가 닫히지 않았습니다.",
