  ["The pattern is broken; it is read as plain text."] = "패턴이 잘못되어 일반 텍스트로 읽습니다.",
  -- the broker displays' feed (ADR 0043, 31.10.2026)
  ["Click: open. Right click: its settings."] = "클릭: 열기. 오른쪽 클릭: 설정.",
  -- the bag addons' item sets and EllesmereUI's section (ADR 0043, 31.10.2026)
  ["Minimap buttons"] = "미니맵 버튼",
  ["Buttons"] = "버튼",
  ["Open Bastian's settings"] = "Bastian's 설정 열기",
  ["Add a Broker Plugin block to a data bar and pick a Bastian's feed."] = "데이터 바에 Broker Plugin 블록을 추가하고 Bastian's 피드를 고르세요.",

  -- Welcome, Suite page, Help page, app pages, Words (01.11.2026)
  ["%d of %d"] = "%d / %d",
  ["/bastians: hub | suite | help | news | about | addons | welcome | log [n] | debug | profile [name] | perf"] = "/bastians: hub | suite | help | news | about | addons | welcome | log [n] | debug | profile [name] | perf",
  ["A Messenger for whispers: the people on the left, the conversation on the right"] = "귓속말용 메신저: 왼쪽에 사람, 오른쪽에 대화",
  ["A creature greets when it shows and plays an emote now and then."] = "생물이 나타날 때 인사하고 가끔 감정 표현을 합니다.",
  ["A name on any page opens its page, its place on the map, the way there and its voice in the Orbiter. The apps talk through Core only, so one that is missing or switched off takes away its button and nothing else; every app can be switched off on the Suite page."] = "어느 페이지에서든 이름을 누르면 그 페이지, 지도상의 위치, 가는 길, 오비터의 목소리가 열립니다. 앱들은 Core를 통해서만 서로 통신하므로, 없거나 꺼진 앱은 그 버튼만 사라질 뿐 나머지는 그대로입니다. 모든 앱은 모음 페이지에서 끌 수 있습니다.",
  ["A note here"] = "여기에 메모",
  ["A note on a page"] = "페이지에 메모",
  ["A note's spot as the goal"] = "메모의 위치를 목적지로",
  ["A page for every NPC, item, quest, object, zone and dungeon"] = "모든 NPC, 아이템, 퀘스트, 오브젝트, 지역, 던전의 페이지",
  ["A quest's places as stops"] = "퀘스트의 장소를 경유지로",
  ["A ready thank-you when someone buffs or resurrects you, or emotes at you"] = "누군가 버프를 걸어 주거나 부활시켜 주거나 감정 표현을 보내면 바로 쓸 수 있는 감사 인사",
  ["A ring of the game's emotes on one key"] = "게임의 감정 표현을 한 키에 담은 링",
  ["A round of several quest stops; what is worth doing nearby"] = "여러 퀘스트 경유지를 도는 순회, 근처에서 할 만한 일",
  ["A round panel of what can be heard around you: the zone, the dungeon, quest givers and their quests, bosses, books"] = "주변에서 들을 수 있는 것의 원형 패널: 지역, 던전, 퀘스트 제공자와 그 퀘스트, 우두머리, 책",
  ["A route to any place: flights, boats, zeppelins, the tram, portals and the hearthstone"] = "어디로든 가는 경로: 비행 경로, 배, 비행선, 지하철, 차원문, 귀환석",
  ["A second button at the minimap that opens these settings."] = "이 설정을 여는 미니맵의 두 번째 버튼입니다.",
  ["A session panel: gold and experience per hour"] = "세션 패널: 시간당 골드와 경험치",
  ["A small explanation under the mouse on every button and setting."] = "모든 버튼과 설정에서 마우스 아래에 짧은 설명을 보여줍니다.",
  ["A spam filter, long texts sent in parts, copying, web addresses as links"] = "스팸 필터, 긴 글을 나눠 보내기, 복사, 웹 주소를 링크로",
  ["A step list with times, a dotted line on the map and the minimap, an arrow to the next step"] = "시간이 적힌 단계 목록, 지도와 미니맵의 점선, 다음 단계를 가리키는 화살표",
  ["Accept and hand in"] = "수락 및 완료",
  ["Add a note"] = "메모 추가",
  ["After an update: a dot on the minimap button and one chat line (Always), the line at most weekly, or nothing (Never). /bastians news lists everything."] = "업데이트 후: 미니맵 버튼의 점과 채팅 한 줄(항상), 그 줄은 최대 주 1회, 또는 없음(안 함). /bastians news가 모두 보여줍니다.",
  ["An item's price on its page"] = "아이템 페이지에 표시되는 가격",
  ["Arrivals (you are there)"] = "도착 (목적지에 있을 때)",
  ["Ask another character for an item; its next mailbox visit fills the mail"] = "다른 캐릭터에게 아이템을 요청합니다. 그 캐릭터가 다음에 우편함을 열 때 우편이 채워집니다.",
  ["At quest givers: accept and hand in, skip gossip (off until you turn them on)"] = "퀘스트 제공자에서: 수락과 완료, 대화 건너뛰기 (켜기 전까지 꺼짐)",
  ["At the mailbox: Take all, Send to your characters, the last recipient"] = "우편함에서: 모두 받기, 내 캐릭터에게 보내기, 마지막 수신자",
  ["At the merchant: sell junk with Undo, repair, restock; Alt-click buys a stack"] = "상인에게서: 잡동사니 판매(되돌리기 가능), 수리, 재보충. Alt-클릭으로 한 묶음 구매",
  ["Back"] = "뒤로",
  ["Bastian's Gestures: a ring of emotes, your own lines and the suite's actions on one key."] = "바스티안의 제스처: 감정 표현, 나만의 문구, 스위트의 동작을 한 키에 담은 링. 누군가 버프를 걸어 주면 바로 쓸 수 있는 감사 인사..",
  ["Your own lines in a file of your own (Bastians_MyLines)"] = "나만의 파일에 담는 나만의 문구 (Bastians_MyLines)",
  ["Hand-written lines in six moods, fitted to the person, the hour and the weather"] = "상대와 시간, 날씨에 맞춘 여섯 가지 분위기의 손글씨 문구",
  ["Bastian's Courtesy: when someone is kind to you, four fitting answers on a ring, one click away."] = "Bastian's Courtesy: 누군가 호의를 베풀면 상황에 맞는 네 가지 답이 링에 나타나 한 번의 클릭으로 답합니다.",
  ["Bastian's Gold Adventures: a book of gold strategies, told in game"] = "바스티안의 골드 소문: 게임 안에서 들려주는 골드 전략서",
  ["Bastian's Suite is Azeroth, told in your own way. You might be the Wanderer, who explores this new world on their own, guided only by the voices of the land. Or you might be the Scholar, with every quest, creature, item and place one click from its page, its spot on the map and the way there."] = "바스티안의 모음은 당신만의 방식으로 들려주는 아제로스입니다. 땅의 목소리에만 이끌려 이 새로운 세계를 홀로 탐험하는 방랑자가 될 수도 있고, 모든 퀘스트, 생물, 아이템, 장소가 클릭 한 번이면 그 페이지, 지도상의 위치, 가는 길로 이어지는 학자가 될 수도 있습니다.",
  ["Bastian's minimap: the game's minimap in a frame of ours, with styles and a search"] = "바스티안의 미니맵: 게임 미니맵을 우리만의 테두리에 담고 스타일과 검색을 더했습니다",
  ["Bastian's: /bastians (the settings), /bs (the search)"] = "Bastian's: /bastians (설정), /bs (검색)",
  ["Both"] = "둘 다",
  ["Built per client from the client's own files and the licensed sources, updated daily"] = "클라이언트별로 클라이언트 자체 파일과 라이선스된 출처로 만들며 매일 갱신됩니다",
  ["Clear the screen hides what you ticked under 'Hidden by the key' and brings it back; the search and the hub have keys too. Set them in the game's Key Bindings under Bastian's."] = "'화면 비우기'는 '단축키로 숨김'에서 체크한 것을 숨기고 다시 보여 줍니다. 검색과 허브에도 단축키가 있습니다. 게임의 단축키 설정에서 Bastian's 항목에 지정하세요.",
  ["Every app can be switched off on the Suite page of the settings; the others keep working. Missing or outdated parts are said in chat at login."] = "모든 앱은 설정의 모음 페이지에서 끌 수 있으며 나머지는 계속 작동합니다. 없거나 오래된 부분은 접속할 때 채팅으로 알려줍니다.",
  ["Every app on, the Orbiter too."] = "모든 앱을 켭니다. 오비터도 함께 켭니다.",
  ["Every app on, the Orbiter too; decide later on the Suite page."] = "모든 앱을 켭니다. 오비터도 함께 켜며, 나중에 모음 페이지에서 정할 수 있습니다.",
  ["Every character's bags, bank, mail and equipment, read from any of them"] = "모든 캐릭터의 가방, 은행, 우편, 장비를 어느 캐릭터에서든 확인",
  ["Every look setting at once: the renderer, the colours, the fonts. Change anything after and save your own."] = "모든 외형 설정을 한 번에: 렌더러, 색상, 글꼴. 이후 무엇이든 바꾸고 나만의 프리셋으로 저장하세요.",
  ["Every quest's text, read aloud with Spoken or the game's voice"] = "모든 퀘스트 텍스트를 Spoken 또는 게임 음성으로 읽어줍니다",
  ["Every quest, creature, item and place one click from its page, its spot on the map and the way there: every app on, every minimap button, the tracker wide."] = "모든 퀘스트, 생물, 아이템, 장소가 클릭 한 번이면 그 페이지, 지도상의 위치, 가는 길로 연결됩니다. 모든 앱 켜짐, 모든 미니맵 버튼, 넓은 추적기.",
  ["Every step of the suite in the chat, for a bug report; /bastians log shows the last lines."] = "버그 신고를 위해 스위트의 모든 동작을 채팅에 표시합니다. /bastians log가 마지막 줄들을 보여줍니다.",
  ["Every text of the suite larger or smaller, in percent."] = "스위트의 모든 글자를 퍼센트 단위로 크게 또는 작게 합니다.",
  ["Everything"] = "전부",
  ["Everything kept over /reload and logout"] = "/reload와 로그아웃 후에도 유지되는 모든 것",
  ["Explore this new world on your own, guided only by the voices of the land: the Orbiter, the chat, the map with a quiet minimap, your gestures. No quest log, no browser, no routes; one key clears the screen."] = "땅의 목소리에만 이끌려 이 새로운 세계를 홀로 탐험하세요: 오비터, 채팅, 조용한 미니맵이 있는 지도, 나만의 제스처. 퀘스트 로그도, 브라우저도, 경로도 없고, 키 하나로 화면이 깨끗해집니다.",
  ["Farm spots and strategies with their gold per hour"] = "시간당 골드가 표시된 파밍 장소와 공략",
  ["Farm spots on the map"] = "지도의 파밍 장소",
  ["Fastest, safest or without flight costs; home and every way back"] = "가장 빠르게, 가장 안전하게, 또는 비행 비용 없이. 집으로, 그리고 돌아오는 모든 길",
  ["Go there"] = "가기",
  ["Help"] = "도움말",
  ["How do you want to play?"] = "어떻게 플레이하고 싶으세요?",
  ["How long the mouse rests before the explanation shows."] = "설명이 나타나기 전에 마우스가 머무는 시간입니다.",
  ["How many lines of the suite a tooltip may add: prices, notes, who has it."] = "툴팁에 스위트가 추가할 수 있는 줄 수: 가격, 메모, 누가 가지고 있는지.",
  ["How much of the world shows through the windows' ground."] = "창 배경 너머로 세계가 얼마나 비쳐 보일지 정합니다.",
  ["How should it look?"] = "어떤 모습이 좋으세요?",
  ["How the apps link"] = "앱들이 연결되는 방식",
  ["IDs and item level on tooltips; a word when gear breaks or the bags fill"] = "툴팁에 ID와 아이템 레벨 표시, 장비가 부서지거나 가방이 찰 때 알림",
  ["Into the world"] = "세계 속으로",
  ["Keys"] = "단축키",
  ["Leads in the tracker"] = "추적기의 단서",
  ["Lists by type with filters: where, level, rank, services"] = "유형별 목록과 필터: 장소, 레벨, 등급, 서비스",
  ["Lists you can hide, share with your group or guild, or paste as text"] = "숨기거나, 파티·길드와 공유하거나, 텍스트로 붙여 넣을 수 있는 목록",
  ["Live prices"] = "실시간 가격",
  ["Live prices in the book"] = "책 속의 실시간 가격",
  ["Live prices on every page from your scans"] = "내 스캔으로 얻은, 모든 페이지의 실시간 가격",
  ["Loaded only when an app asks for it"] = "앱이 요청할 때만 불러옵니다",
  ["Next"] = "다음",
  ["Notes and shared spots on the map"] = "지도의 메모와 공유된 장소",
